import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

public class Solution {
    /** Uma camada: arquivos com conteúdo, whiteouts (marcas de remoção) e diretórios opacos. */
    static final class Camada {
        private final Map<String, String> arquivos = new HashMap<>();
        private final Set<String> whiteouts = new HashSet<>();
        private final Set<String> opacos = new HashSet<>();

        Camada arquivo(String caminho, String conteudo) {
            String p = normalizar(caminho);
            if (p.equals("/")) throw new IllegalArgumentException("a raiz não é arquivo");
            if (conteudo == null) throw new IllegalArgumentException("conteúdo nulo");
            arquivos.put(p, conteudo);
            whiteouts.remove(p);
            return this;
        }

        /** Marca o caminho (arquivo ou diretório inteiro) como removido. Apaga o que esta camada tinha dele. */
        Camada whiteout(String caminho) {
            String p = normalizar(caminho);
            if (p.equals("/")) throw new IllegalArgumentException("a raiz não pode ser removida");
            arquivos.keySet().removeIf(a -> a.equals(p) || a.startsWith(p + "/"));
            whiteouts.add(p);
            return this;
        }

        /** Marca o diretório como opaco: o conteúdo dele nas camadas de baixo fica escondido. */
        Camada opaco(String diretorio) {
            String p = normalizar(diretorio);
            if (p.equals("/")) throw new IllegalArgumentException("a raiz não pode ser opaca");
            opacos.add(p);
            return this;
        }
    }

    static String normalizar(String caminho) {
        if (caminho == null || caminho.isEmpty() || caminho.charAt(0) != '/') throw new IllegalArgumentException("caminho inválido: " + caminho);
        if (caminho.equals("/")) return "/";
        if (caminho.endsWith("/") || caminho.contains("//")) throw new IllegalArgumentException("caminho inválido: " + caminho);
        for (String parte : caminho.substring(1).split("/")) {
            if (parte.equals(".") || parte.equals("..")) throw new IllegalArgumentException("caminho inválido: " + caminho);
        }
        return caminho;
    }

    /** O próprio caminho e cada ancestral (sem a raiz): /a/b/c -> /a/b/c, /a/b, /a. */
    private static List<String> comAncestrais(String p) {
        List<String> out = new ArrayList<>();
        String atual = p;
        while (!atual.equals("/") && !atual.isEmpty()) {
            out.add(atual);
            int i = atual.lastIndexOf('/');
            atual = i <= 0 ? "" : atual.substring(0, i);
        }
        return out;
    }

    /** A visão unificada de um OverlayFS: camadas de baixo (somente leitura) e uma camada superior gravável. */
    static final class Overlay {
        private final List<Camada> inferiores; // da mais alta (mais perto do topo) para a mais baixa
        private final Camada superior = new Camada();
        private final Overlay base; // só as camadas inferiores, para saber o que existe "embaixo"
        private int copyUps = 0;

        /** {@code inferiores}: da camada mais alta para a mais baixa (a ordem do lowerdir). */
        Overlay(List<Camada> inferiores) {
            this(inferiores, true);
        }

        private Overlay(List<Camada> inferiores, boolean comBase) {
            if (inferiores == null) throw new IllegalArgumentException("camadas nulas");
            this.inferiores = new ArrayList<>(inferiores);
            this.base = comBase ? new Overlay(inferiores, false) : null;
        }

        private List<Camada> todas() {
            List<Camada> out = new ArrayList<>();
            out.add(superior);
            out.addAll(inferiores);
            return out;
        }

        /** O conteúdo visto pelo container, ou vazio se o arquivo não existe na visão unificada. */
        Optional<String> ler(String caminho) {
            String p = normalizar(caminho);
            if (p.equals("/")) return Optional.empty();
            List<String> cadeia = comAncestrais(p);
            for (Camada c : todas()) {
                String conteudo = c.arquivos.get(p);
                if (conteudo != null) return Optional.of(conteudo);
                for (String a : cadeia) if (c.whiteouts.contains(a)) return Optional.empty();
                for (String a : cadeia.subList(1, cadeia.size())) if (c.opacos.contains(a)) return Optional.empty();
            }
            return Optional.empty();
        }

        /** Todos os arquivos visíveis, em ordem alfabética. */
        List<String> arquivos() {
            Set<String> candidatos = new TreeSet<>();
            for (Camada c : todas()) candidatos.addAll(c.arquivos.keySet());
            List<String> out = new ArrayList<>();
            for (String p : candidatos) if (ler(p).isPresent()) out.add(p);
            return out;
        }

        /** Existe se for arquivo visível ou diretório com algum arquivo visível dentro. */
        boolean existe(String caminho) {
            String p = normalizar(caminho);
            if (p.equals("/")) return true;
            for (String a : arquivos()) if (a.equals(p) || a.startsWith(p + "/")) return true;
            return false;
        }

        /** Os filhos diretos de um diretório na visão unificada; subdiretórios terminam em "/". */
        List<String> listar(String diretorio) {
            String d = normalizar(diretorio);
            String prefixo = d.equals("/") ? "/" : d + "/";
            Set<String> filhos = new TreeSet<>();
            for (String a : arquivos()) {
                if (!a.startsWith(prefixo)) continue;
                String resto = a.substring(prefixo.length());
                int i = resto.indexOf('/');
                filhos.add(i < 0 ? resto : resto.substring(0, i + 1));
            }
            return new ArrayList<>(filhos);
        }

        /** Grava o arquivo na camada superior. Se ele vinha de uma camada de baixo, faz copy-up. */
        void escrever(String caminho, String conteudo) {
            String p = normalizar(caminho);
            if (conteudo == null) throw new IllegalArgumentException("conteúdo nulo");
            if (!superior.arquivos.containsKey(p) && base.ler(p).isPresent() && ler(p).isPresent()) copyUps++;
            // recriar um diretório removido o torna opaco: o que havia embaixo não volta
            for (String a : comAncestrais(p).subList(1, comAncestrais(p).size())) {
                if (superior.whiteouts.remove(a)) superior.opacos.add(a);
            }
            superior.arquivo(p, conteudo);
        }

        /** Remove arquivo ou diretório. Devolve false se não existia na visão unificada. */
        boolean remover(String caminho) {
            String p = normalizar(caminho);
            if (p.equals("/") || !existe(p)) return false;
            superior.arquivos.keySet().removeIf(a -> a.equals(p) || a.startsWith(p + "/"));
            superior.whiteouts.removeIf(w -> w.startsWith(p + "/"));
            superior.opacos.removeIf(o -> o.equals(p) || o.startsWith(p + "/"));
            if (base.existe(p)) {
                superior.whiteouts.add(p);
            }
            return true;
        }

        int copyUps() { return copyUps; }

        /** Como o docker diff: "A" criado, "C" alterado (veio de baixo) e "D" removido, em ordem de caminho. */
        List<String> diff() {
            TreeMap<String, String> linhas = new TreeMap<>();
            for (String a : superior.arquivos.keySet()) linhas.put(a, base.ler(a).isPresent() ? "C" : "A");
            for (String w : superior.whiteouts) linhas.put(w, "D");
            List<String> out = new ArrayList<>();
            for (Map.Entry<String, String> e : linhas.entrySet()) out.add(e.getValue() + " " + e.getKey());
            return out;
        }
    }
}

