import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

class SolutionTest {
    static Solution.Camada camada() { return new Solution.Camada(); }

    /** Imagem de 3 camadas, da mais alta para a mais baixa: app, jre, base. */
    static List<Solution.Camada> imagem() {
        Solution.Camada app = camada().arquivo("/app/app.jar", "jar-v1").arquivo("/etc/app.conf", "debug=true");
        Solution.Camada jre = camada().arquivo("/opt/java/bin/java", "jvm");
        Solution.Camada base = camada()
            .arquivo("/etc/app.conf", "debug=false")
            .arquivo("/etc/hostname", "base")
            .arquivo("/bin/sh", "sh")
            .arquivo("/usr/share/doc/readme", "r")
            .arquivo("/usr/share/doc/changes", "c")
            .arquivo("/usr/lib/libc.so", "libc");
        return List.of(app, jre, base);
    }

    static Solution.Overlay overlay() { return new Solution.Overlay(imagem()); }

    static String ler(Solution.Overlay o, String caminho) { return o.ler(caminho).orElse("<ausente>"); }

    // ---------- leitura de cima para baixo ----------

    @Test void camadaMaisAltaVence() {
        assertEquals("debug=true", ler(overlay(), "/etc/app.conf"));
    }

    @Test void leDeBaixoQuandoOTopoNaoTem() {
        Solution.Overlay o = overlay();
        assertEquals("base", ler(o, "/etc/hostname"));
        assertEquals("jvm", ler(o, "/opt/java/bin/java"));
        assertEquals("sh", ler(o, "/bin/sh"));
    }

    @Test void inexistenteEDiretorioNaoSaoArquivos() {
        Solution.Overlay o = overlay();
        assertEquals(Optional.empty(), o.ler("/nada"));
        assertEquals(Optional.empty(), o.ler("/usr/share"));
        assertEquals(Optional.empty(), o.ler("/"));
    }

    @Test void conteudoVazioEUmArquivoDeVerdade() {
        Solution.Overlay o = new Solution.Overlay(List.of(camada().arquivo("/vazio", "")));
        assertEquals(Optional.of(""), o.ler("/vazio"));
        assertTrue(o.existe("/vazio"));
    }

    // ---------- copy-up ----------

    @Test void escreverArquivoNovoNaoFazCopyUp() {
        Solution.Overlay o = overlay();
        o.escrever("/tmp/novo", "x");
        assertEquals("x", ler(o, "/tmp/novo"));
        assertEquals(0, o.copyUps());
        assertEquals(List.of("A /tmp/novo"), o.diff());
    }

    @Test void escreverEmArquivoDeBaixoFazCopyUp() {
        Solution.Overlay o = overlay();
        o.escrever("/etc/hostname", "web-1");
        assertEquals("web-1", ler(o, "/etc/hostname"));
        assertEquals(1, o.copyUps());
        assertEquals(List.of("C /etc/hostname"), o.diff());
    }

    @Test void aImagemNaoMudaQuandoOContainerEscreve() {
        List<Solution.Camada> img = imagem();
        Solution.Overlay a = new Solution.Overlay(img);
        a.escrever("/etc/hostname", "web-1");
        a.remover("/bin/sh");
        Solution.Overlay b = new Solution.Overlay(img);
        assertEquals("base", ler(b, "/etc/hostname"));
        assertEquals("sh", ler(b, "/bin/sh"));
        assertEquals(List.of(), b.diff());
    }

    @Test void segundaEscritaNoMesmoArquivoNaoRepeteOCopyUp() {
        Solution.Overlay o = overlay();
        o.escrever("/etc/hostname", "um");
        o.escrever("/etc/hostname", "dois");
        assertEquals("dois", ler(o, "/etc/hostname"));
        assertEquals(1, o.copyUps());
    }

    @Test void copyUpsSaoContadosPorArquivo() {
        Solution.Overlay o = overlay();
        o.escrever("/etc/hostname", "a");
        o.escrever("/bin/sh", "b");
        o.escrever("/novo", "c");
        assertEquals(2, o.copyUps());
    }

    @Test void containersDaMesmaImagemTemCamadasGravaveisIndependentes() {
        List<Solution.Camada> img = imagem();
        Solution.Overlay a = new Solution.Overlay(img);
        Solution.Overlay b = new Solution.Overlay(img);
        a.escrever("/etc/hostname", "a");
        assertEquals("base", ler(b, "/etc/hostname"));
        assertEquals(0, b.copyUps());
    }

    // ---------- whiteout ----------

    @Test void removerArquivoDeBaixoCriaWhiteout() {
        Solution.Overlay o = overlay();
        assertTrue(o.remover("/bin/sh"));
        assertEquals(Optional.empty(), o.ler("/bin/sh"));
        assertFalse(o.existe("/bin/sh"));
        assertEquals(List.of("D /bin/sh"), o.diff());
        assertFalse(o.arquivos().contains("/bin/sh"));
    }

    @Test void removerArquivoSoDaSuperiorNaoCriaWhiteout() {
        Solution.Overlay o = overlay();
        o.escrever("/tmp/x", "1");
        assertTrue(o.remover("/tmp/x"));
        assertEquals(Optional.empty(), o.ler("/tmp/x"));
        assertEquals(List.of(), o.diff());
    }

    @Test void removerArquivoComCopyUpEscondeAteAVersaoDeBaixo() {
        Solution.Overlay o = overlay();
        o.escrever("/etc/hostname", "web-1");
        assertTrue(o.remover("/etc/hostname"));
        assertEquals(Optional.empty(), o.ler("/etc/hostname"));
        assertEquals(List.of("D /etc/hostname"), o.diff());
    }

    @Test void removerInexistenteOuRaizDevolveFalse() {
        Solution.Overlay o = overlay();
        assertFalse(o.remover("/nada"));
        assertFalse(o.remover("/usr/nada/mais"));
        assertFalse(o.remover("/"));
        assertTrue(o.remover("/bin/sh"));
        assertFalse(o.remover("/bin/sh"));
        assertEquals(List.of("D /bin/sh"), o.diff());
    }

    @Test void removerDiretorioEscondeTudoAbaixoDele() {
        Solution.Overlay o = overlay();
        assertTrue(o.remover("/usr/share/doc"));
        assertEquals(Optional.empty(), o.ler("/usr/share/doc/readme"));
        assertEquals(Optional.empty(), o.ler("/usr/share/doc/changes"));
        assertFalse(o.existe("/usr/share/doc"));
        assertEquals("libc", ler(o, "/usr/lib/libc.so"));
        assertEquals(List.of("D /usr/share/doc"), o.diff());
        assertEquals(List.of("lib/"), o.listar("/usr"));
    }

    @Test void recriarArquivoRemovidoNaoContaCopyUp() {
        Solution.Overlay o = overlay();
        o.remover("/etc/hostname");
        o.escrever("/etc/hostname", "novo");
        assertEquals("novo", ler(o, "/etc/hostname"));
        assertEquals(0, o.copyUps());
        assertEquals(List.of("C /etc/hostname"), o.diff());
    }

    @Test void whiteoutDeUmaCamadaDeBaixoEscondeAindaMaisBaixo() {
        Solution.Camada topo = camada().whiteout("/etc/hostname");
        Solution.Camada fundo = camada().arquivo("/etc/hostname", "base").arquivo("/etc/outro", "o");
        Solution.Overlay o = new Solution.Overlay(List.of(topo, fundo));
        assertEquals(Optional.empty(), o.ler("/etc/hostname"));
        assertEquals("o", ler(o, "/etc/outro"));
        assertEquals(List.of("/etc/outro"), o.arquivos());
    }

    @Test void whiteoutDeDiretorioNaCamadaEscondeOsFilhosDeBaixo() {
        Solution.Camada topo = camada().whiteout("/usr/share/doc").arquivo("/usr/share/doc/novo", "n");
        Solution.Camada fundo = camada().arquivo("/usr/share/doc/velho", "v").arquivo("/usr/bin/x", "x");
        Solution.Overlay o = new Solution.Overlay(List.of(topo, fundo));
        assertEquals("n", ler(o, "/usr/share/doc/novo"));
        assertEquals(Optional.empty(), o.ler("/usr/share/doc/velho"));
        assertEquals("x", ler(o, "/usr/bin/x"));
    }

    @Test void whiteoutNaCamadaApagaOQueEstaCamadaTinha() {
        Solution.Camada c = camada().arquivo("/a/b", "1").arquivo("/a/c", "2").whiteout("/a");
        Solution.Overlay o = new Solution.Overlay(List.of(c));
        assertEquals(List.of(), o.arquivos());
    }

    // ---------- diretório opaco ----------

    @Test void recriarUmDiretorioRemovidoNaoTrazOConteudoDeVolta() {
        Solution.Overlay o = overlay();
        o.remover("/usr/share/doc");
        o.escrever("/usr/share/doc/novo", "n");
        assertEquals("n", ler(o, "/usr/share/doc/novo"));
        assertEquals(Optional.empty(), o.ler("/usr/share/doc/readme"));
        assertEquals(List.of("novo"), o.listar("/usr/share/doc"));
        assertEquals(List.of("A /usr/share/doc/novo"), o.diff());
    }

    @Test void opacoEscondeSoOQueEstaAbaixo() {
        Solution.Camada topo = camada().arquivo("/etc/top", "t");
        Solution.Camada meio = camada().opaco("/etc").arquivo("/etc/meio", "m");
        Solution.Camada fundo = camada().arquivo("/etc/fundo", "f").arquivo("/bin/sh", "sh");
        Solution.Overlay o = new Solution.Overlay(List.of(topo, meio, fundo));
        assertEquals("t", ler(o, "/etc/top"));
        assertEquals("m", ler(o, "/etc/meio"));
        assertEquals(Optional.empty(), o.ler("/etc/fundo"));
        assertEquals("sh", ler(o, "/bin/sh"));
        assertEquals(List.of("meio", "top"), o.listar("/etc"));
    }

    @Test void opacoValeParaSubdiretoriosTambem() {
        Solution.Camada topo = camada().opaco("/etc");
        Solution.Camada fundo = camada().arquivo("/etc/conf.d/a", "a");
        Solution.Overlay o = new Solution.Overlay(List.of(topo, fundo));
        assertEquals(Optional.empty(), o.ler("/etc/conf.d/a"));
        assertEquals(List.of(), o.listar("/etc"));
    }

    @Test void removerEmSeguidaRecriarFuncionaVariasVezes() {
        Solution.Overlay o = overlay();
        o.remover("/usr/share/doc");
        o.escrever("/usr/share/doc/a", "1");
        assertTrue(o.remover("/usr/share/doc"));
        assertEquals(List.of("D /usr/share/doc"), o.diff());
        o.escrever("/usr/share/doc/b", "2");
        assertEquals(List.of("b"), o.listar("/usr/share/doc"));
    }

    @Test void whiteoutDeUmDiretorioNaoAtingeNomesComOMesmoPrefixo() {
        Solution.Camada c = camada().arquivo("/ab", "irmao").arquivo("/a/b", "filho").whiteout("/a");
        Solution.Overlay o = new Solution.Overlay(List.of(c));
        assertEquals(List.of("/ab"), o.arquivos());
    }

    @Test void removerODiretorioSubstituiOsWhiteoutsDosFilhos() {
        Solution.Overlay o = overlay();
        assertTrue(o.remover("/usr/share/doc/readme"));
        assertEquals(List.of("D /usr/share/doc/readme"), o.diff());
        assertTrue(o.remover("/usr/share/doc"));
        assertEquals(List.of("D /usr/share/doc"), o.diff());
    }

    // ---------- listagem ----------

    @Test void listaAVisaoUnificadaEmOrdem() {
        Solution.Overlay o = overlay();
        assertEquals(List.of("app/", "bin/", "etc/", "opt/", "usr/"), o.listar("/"));
        assertEquals(List.of("app.conf", "hostname"), o.listar("/etc"));
        assertEquals(List.of("lib/", "share/"), o.listar("/usr"));
    }

    @Test void listaMostraArquivosNovosEEscondeRemovidos() {
        Solution.Overlay o = overlay();
        o.escrever("/etc/novo", "n");
        o.remover("/etc/hostname");
        assertEquals(List.of("app.conf", "novo"), o.listar("/etc"));
    }

    @Test void diretorioSemNadaVisivelListaVazio() {
        Solution.Overlay o = overlay();
        assertEquals(List.of(), o.listar("/nada"));
        assertEquals(List.of(), o.listar("/etc/app.conf"));
    }

    @Test void existeParaDiretorios() {
        Solution.Overlay o = overlay();
        assertTrue(o.existe("/"));
        assertTrue(o.existe("/usr/share"));
        assertTrue(o.existe("/etc/app.conf"));
        assertFalse(o.existe("/us"));
        assertFalse(o.existe("/usr/sha"));
    }

    @Test void arquivosVisiveisEmOrdemAlfabetica() {
        Solution.Overlay o = overlay();
        o.remover("/usr/share/doc/readme");
        List<String> esperado = List.of("/app/app.jar", "/bin/sh", "/etc/app.conf", "/etc/hostname", "/opt/java/bin/java", "/usr/lib/libc.so", "/usr/share/doc/changes");
        assertEquals(esperado, o.arquivos());
    }

    // ---------- diff ----------

    @Test void diffMistoEmOrdemDeCaminho() {
        Solution.Overlay o = overlay();
        o.escrever("/var/log/app.log", "x");
        o.escrever("/etc/hostname", "web-1");
        o.remover("/usr/share/doc");
        o.remover("/bin/sh");
        assertEquals(List.of("D /bin/sh", "C /etc/hostname", "D /usr/share/doc", "A /var/log/app.log"), o.diff());
    }

    // ---------- validação ----------

    @Test void caminhosInvalidosLancamExcecao() {
        Solution.Overlay o = overlay();
        String[] ruins = { "", "etc/app.conf", "/etc/", "/etc//app.conf", "/etc/../bin/sh", "/./etc", "/etc/." };
        for (String ruim : ruins) {
            assertThrows(IllegalArgumentException.class, () -> o.ler(ruim), "ler: '" + ruim + "'");
            assertThrows(IllegalArgumentException.class, () -> o.escrever(ruim, "x"), "escrever: '" + ruim + "'");
            assertThrows(IllegalArgumentException.class, () -> o.remover(ruim), "remover: '" + ruim + "'");
        }
        assertThrows(IllegalArgumentException.class, () -> o.ler(null));
        assertThrows(IllegalArgumentException.class, () -> camada().arquivo("/", "x"));
        assertThrows(IllegalArgumentException.class, () -> camada().whiteout("/"));
        assertThrows(IllegalArgumentException.class, () -> camada().opaco("/"));
    }

    @Test void conteudoNuloELancaExcecao() {
        assertThrows(IllegalArgumentException.class, () -> overlay().escrever("/x", null));
        assertThrows(IllegalArgumentException.class, () -> camada().arquivo("/x", null));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Overlay(null));
    }

    // ---------- desempenho ----------

    @Test void centenasDeArquivosEmVariasCamadas() {
        Solution.Camada a = camada();
        Solution.Camada b = camada();
        Solution.Camada c = camada();
        for (int i = 0; i < 600; i++) {
            c.arquivo("/dados/d" + (i % 20) + "/f" + i, "c" + i);
            if (i % 2 == 0) b.arquivo("/dados/d" + (i % 20) + "/f" + i, "b" + i);
            if (i % 3 == 0) a.arquivo("/dados/d" + (i % 20) + "/f" + i, "a" + i);
        }
        Solution.Overlay o = new Solution.Overlay(List.of(a, b, c));
        long inicio = System.nanoTime();
        assertEquals("a0", ler(o, "/dados/d0/f0"));
        assertEquals("b2", ler(o, "/dados/d2/f2"));
        assertEquals("c1", ler(o, "/dados/d1/f1"));
        for (int i = 0; i < 20; i += 2) o.remover("/dados/d" + i);
        assertEquals(300, o.arquivos().size());
        assertEquals(10, o.listar("/dados").size());
        assertTrue((System.nanoTime() - inicio) / 1_000_000 < 5_000, "deveria terminar em poucos segundos");
    }
